#!/usr/bin/env node
/**
 * Offline Issue #140 clone catalog-parity gate. Takes two private manifest JSON
 * files generated by scripts/issue-140-staging-manifest.sql, not DB credentials.
 * This script NEVER connects to PostgreSQL, restores, migrates, or writes data.
 * Usage: node scripts/issue-140-verify-clone-parity.mjs <staging-catalog.json> <clone-catalog.json>
 */
import { readFile } from 'node:fs/promises';

const CRITICAL = ['schemas','roles','memberships','extensions','relations','columns',
  'constraints','views','default_acl','policies','indexes','triggers','functions'];
const normalize = value => {
  if (Array.isArray(value)) return value.map(normalize).sort((a,b) => JSON.stringify(a).localeCompare(JSON.stringify(b)));
  if (value && typeof value === 'object') return Object.fromEntries(Object.keys(value).sort().map(k=>[k,normalize(value[k])]));
  return value;
};
const same = (a,b) => JSON.stringify(normalize(a)) === JSON.stringify(normalize(b));

export function compareCatalogs(source,clone) {
  const failures = [];
  if (!source || !clone || typeof source !== 'object' || typeof clone !== 'object' || Array.isArray(source) || Array.isArray(clone)) {
    return { status:'BLOCKED', failures:['invalid_catalog'], counts:{} };
  }
  if (!/^17\./.test(String(source.database_version ?? '')) || !/^17\./.test(String(clone.database_version ?? ''))) failures.push('postgres_17_required');
  if (!same(source.checkpoint,clone.checkpoint) || !source.checkpoint) failures.push('checkpoint_drift');
  if ((source.foreign_servers ?? -1) !== 0 || (clone.foreign_servers ?? -1) !== 0) failures.push('foreign_server_requires_manual_review');
  const counts={};
  for (const key of CRITICAL) {
    const one=source[key],two=clone[key];
    if (!Array.isArray(one) || !Array.isArray(two)) { failures.push(key+'_missing'); continue; }
    counts[key]={staging:one.length,clone:two.length};
    if (!same(one,two)) failures.push(key+'_drift');
  }
  if (!same(source.postgrest_catalog_settings,clone.postgrest_catalog_settings)) failures.push('postgrest_settings_drift');
  // Header-only comparison: even perfect equivalence does not verify data,
  // Auth semantics, PostgREST environment config, or operational readiness.
  return { status:failures.length ? 'BLOCKED' : 'CATALOG_PARITY_ONLY_NOT_RELEASE_APPROVAL', failures, counts };
}

async function main() {
  if(process.argv.length!==4) throw new Error('Usage: node scripts/issue-140-verify-clone-parity.mjs <staging-catalog.json> <clone-catalog.json>');
  const [a,b]=await Promise.all(process.argv.slice(2).map(path=>readFile(path,'utf8').then(JSON.parse)));
  const result=compareCatalogs(a,b);
  process.stdout.write(JSON.stringify(result,null,2)+'\n');
  if(result.status==='BLOCKED') process.exitCode=2;
}
if (process.argv[1] && /issue-140-verify-clone-parity\.mjs$/.test(process.argv[1])) {
  main().catch(()=>{process.stderr.write('BLOCKED: catalog files unavailable or invalid\n');process.exitCode=2;});
}
